import React from 'react';

const About = () => (
  <section id="about">
    <div className="container">
      <h2>About Me</h2>
      <p>
        I am a passionate DevOps Engineer with over 5 years of experience in automating deployments, managing cloud infrastructures, and optimizing CI/CD pipelines. Based in Lahore, Pakistan, I specialize in AWS, Kubernetes, and modern DevOps tools to deliver scalable solutions.
      </p>
    </div>
  </section>
);

export default About;
